import sys,json,time,hashlib,datetime,subprocess,os
from pathlib import Path
R=Path(__file__).resolve().parent;S=R.parents[2]/'native-ui-agent/scripts';sys.path.insert(0,str(S));import acceptance
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
# Environment-only iOS validation on original files; never invent two independent panels.
envs={'evaluator_sha256':sha(S/'acceptance.py'),'scope':'Native environment verification only; independent two-panel acceptance CLI not run.','runs':{}}
for scenario in ['normal','narrow-large']:
 key='ios-'+scenario;p=R/'captures'/key/'observation.json'
 envs['runs'][key]={'observation_sha256':sha(p),'environment':acceptance.environment(json.loads(p.read_text()),json.loads((R/'environment'/f'{key}.json').read_text()),'ios')}
(R/'ios-environment-checks.json').write_text(json.dumps(envs,indent=2)+'\n')
commands=[json.loads(line)for line in(R/'commands.jsonl').read_text().splitlines()]
native=[c for c in commands if any(x.endswith(('/ios_observe.py','/android_observe.py'))for x in c['argv'])]
runs=[]
for f in sorted((R/'captures').glob('*/manifest.json')):
 m=json.loads(f.read_text());cmd=next(c for c in native if str(f.parent)in c['argv'])
 row={'run':f.parent.name,'command_wall_seconds':cmd['duration_seconds'],'status':m['status'],'native_test_count':m.get('native_test_count'),'manifest_sha256':sha(f),'native_timings':m.get('timings'),'junit_test_seconds':m.get('native_counts',{}).get('time'),'build_cache_hit':m.get('build_cache',{}).get('hit')}
 o=json.loads((f.parent/'observation.json').read_text());row.update(snapshot_count=len(o['snapshots']),state_count=len(o.get('state_captures',[])),all_states_complete=all(s['complete']for s in o.get('state_captures',[])),observation_sha256=sha(f.parent/'observation.json'))
 runs.append(row)
(R/'phase-times.json').write_text(json.dumps({'measured_epoch':time.time(),'start_clock_utc':'2026-10-22T00:48:11Z','note':'Command durations are actual measured wall time. Native commands ran across platforms in parallel; totals must not be added to infer elapsed time. Separate read/authoring/visual-inspection stopwatch was not available; exact SDK/check durations and sequence are retained. Root-requested hold spans the recorded original failure/inspection and revision2 launch.','runs':runs,'bootstrap_seconds':next(c['duration_seconds']for c in commands if any(x.endswith('/dispatch-forward/bootstrap.py')for x in c['argv']))},indent=2)+'\n')
# Immutable source identity check.
impl=json.loads((R/'implementation-seal.json').read_text());matches={p:sha(R/p)==digest for p,digest in impl['files'].items()}
# EagerPreflight was deliberately added after the first source seal; original component sources remain identical.
(R/'source-recheck.json').write_text(json.dumps({'epoch':time.time(),'all_original_implementation_files_unchanged':all(matches.values()),'files':matches,'component_source_sha256':{p.name:sha(p)for p in(R/'sources').glob('*')}},indent=2)+'\n')
# Record own clone setup diff (dependency harness only plus component sources already separate).
for name in ['reply','alerttoast']:
 repo=R/'cache/generic-host'/name
 (R/f'dependency-host-{name}.patch').write_bytes(subprocess.check_output(['git','diff','--binary'],cwd=repo))
summary=[]
for key in ['android-normal-v2','android-narrow-large-v2','ios-normal','ios-narrow-large']:
 report=json.loads((R/'checks'/f'{key}.json').read_text());plan=json.loads((R/'generated'/key.removesuffix('-v2')/'plan.json').read_text())
 summary.append({'run':key,'counts':report['counts'],'status':report['status'],'matrix_cells':len(plan['matrix_contract']['cells']),'not_applicable_cells':sum(1 for c in plan['matrix_contract']['cells']if c.get('disposition')=='not_applicable')})
(R/'result-summary.json').write_text(json.dumps({'runs':summary,'environment':{**{k:v['environment']['status']for k,v in json.loads((R/'revised-environment-checks.json').read_text())['runs'].items()},**{k:v['environment']['status']for k,v in envs['runs'].items()}},'scope':'Single-context original visual review plus contract-bound native/pixel facts; no independent two-judge acceptance or product study score.','component_fixes':0,'seeded_defects':0},indent=2)+'\n')
a=json.loads((R/'APPROVAL.json').read_text());lines=['# Independent neutral forward probe','', 'The small iOS/Android QuietMomentCard component met its frozen contract on the first implementation. Both platforms were rendered at normal and narrow/large-text configurations. Every final run has 14 passed, 0 failed, 0 unassessed applicable assertions; each 16-cell matrix also contains 2 explicit N/A stimulus cells. No defect was seeded and no component fix was required.','', '| Final run | Original frames | Bound assertions | Environment |','| --- | ---: | --- | --- |']
for s in summary:
 run=next(r for r in runs if r['run']==s['run']);lines.append(f"| {s['run']} | {run['snapshot_count']} | 14/14 passed; 2 N/A | P |")
lines+=['','The design freezes component-owned canvas/accent fills, separate wrapping/overlap propositions, exact native 64-unit band height, both caller titles, activation callback and callback silence after replacement. Zero RGB channel tolerance is used. Pixel results concern the approved sample regions, not every canvas pixel. One review context read the original images; two independent visual judges and panel acceptance are not established.','',f"Design canonical SHA256: `{a['design_lock_sha256']}`.",f"Policy canonical SHA256: `{a['policy_sha256']}`.",'','The iOS normal native viewport is 390×600pt and narrow is 260×600pt; actual Dynamic Type is large/accessibility3, light, ltr. The iPhone 17 simulator uses iOS 26.5; Xcode 27.1 compiles the arm64 host against SDK 27.1. The requested 390 Android viewport is actually 389.81818dp at 2.75 density because the pinned provider uses integer 1072px; narrow is 260dp/715px. Original exact-unit environment checks F/P remain in original-environment-checks.json. After root updated the shared metadata interface, fresh v2 acquisitions use the separately recorded explicit provider encoding with unchanged 390/260 requests and pass P/P. This is a prefreeze tool revision, not a retroactive change to original evidence.','', 'The original bundled iOS LazyVStack capability probe executed 1 test but failed all 6 full-content sweeps because native content height changed by 58–59pt as lower content materialized. Native callbacks and same-process quiet replacement succeeded. Its original failed images, xcresult, logs and unassessed coverage remain intact. A separate original eager-stack generic probe passed all 6 overlapping sweeps; it does not convert the lazy result into a pass.','', 'All component actions dispatched successfully (xcui_tap / compose_onclick), delivered acknowledged, then caller replacement advanced input with no callback in the same PID/session. The iOS narrow states require 2 overlapping frames each, with stable state-bound content heights 798.3333/802.3333pt. Large text and action hyphenate naturally and remain readable.','', 'Native execution wall times (seconds):','', '| Invocation | Seconds | Result |','| --- | ---: | --- |']
for r in runs:lines.append(f"| {r['run']} | {r['command_wall_seconds']:.3f} | {r['status']} |")
lines+=['','The exact commands, exit codes, UTC starts, wall durations and stdout/log hashes are in commands.jsonl. Phase-times.json retains native build/test/export timing and JUnit timing. Parallel intervals overlap; no fictitious independent authoring/reading stopwatch is claimed. The first observed clock is 00:48:11 UTC and final report time is'+datetime.datetime.now(datetime.timezone.utc).isoformat()+'.','', 'No real application page/navigation, Android physical touch, keyboard, lifecycle, screen reader journey, all text styles, whole-canvas color coverage or physical hit area was tested. Generic public iOS AX cannot establish computed SwiftUI font/color/padding. No business study SDK run, subagent, commit, push or Skill write was made by this context. One own reporting-helper syntax error is retained alongside its fix; it is not a tool failure.','', 'Created simulator: A23C7E6D-E267-4C1D-85E0-1A480EFC0BAF. It was shut down after the final capture. The final seal covers all non-cache evidence artifacts and the source snapshots; cached dependencies/build artifacts have their own native manifest hashes.']
(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'summary':summary,'ios_environment':{k:v['environment']['status']for k,v in envs['runs'].items()},'original_sources_unchanged':all(matches.values())}))
